node -e "
import { average } from './stats.mjs';

// Negative values
const neg = [-2, -4];
console.log('negative values:', average(neg));

// Fractional values
const frac = [1.5, 2.5];
console.log('fractional values:', average(frac));

// Mixed positive/negative
const mixed = [1, -1, 2, -2];
console.log('mixed values:', average(mixed));

// Input immutability check
const arr = [1, 2, 3];
const before = JSON.stringify(arr);
average(arr);
const after = JSON.stringify(arr);
console.log('immutability:', before === after ? 'preserved' : 'MUTATED');
console.log('original array:', arr);

// Single element
console.log('single element:', average([42]));

// Zero array
console.log('zero array:', average([0, 0, 0]));
